From a8f9bbb1a61b0b413131373cc14cf9cbdd1fd843 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:07:00 +0100
Subject: [PATCH] draganddrop: read dragged data only when it is needed

Every drag enter and move over a DropArea copied all the dragged data,
so an image dragged from a web browser was transferred again on each
move and a quick drop was lost. The data is now read when it's asked for.

BUG: 505067
---
 .../draganddrop/DeclarativeDragDropEvent.cpp  |  2 +-
 .../draganddrop/DeclarativeMimeData.cpp       | 34 +++++++++++++++++++
 .../draganddrop/DeclarativeMimeData.h         | 13 +++++++
 3 files changed, 48 insertions(+), 1 deletion(-)

diff --git a/src/qmlcontrols/draganddrop/DeclarativeDragDropEvent.cpp b/src/qmlcontrols/draganddrop/DeclarativeDragDropEvent.cpp
index 2295f463..fa953f57 100644
--- a/src/qmlcontrols/draganddrop/DeclarativeDragDropEvent.cpp
+++ b/src/qmlcontrols/draganddrop/DeclarativeDragDropEvent.cpp
@@ -49,7 +49,7 @@ DeclarativeMimeData *DeclarativeDragDropEvent::mimeData()
     if (!m_data && m_event) {
         //         TODO This should be using MimeDataWrapper eventually, although this is an API break,
         //         so will need to be done carefully.
-        m_data.reset(new DeclarativeMimeData(m_event->mimeData()));
+        m_data.reset(DeclarativeMimeData::wrap(m_event->mimeData()));
     }
     return m_data.data();
 }
diff --git a/src/qmlcontrols/draganddrop/DeclarativeMimeData.cpp b/src/qmlcontrols/draganddrop/DeclarativeMimeData.cpp
index 0e7c9d74..bb004afd 100644
--- a/src/qmlcontrols/draganddrop/DeclarativeMimeData.cpp
+++ b/src/qmlcontrols/draganddrop/DeclarativeMimeData.cpp
@@ -30,6 +30,40 @@ DeclarativeMimeData::DeclarativeMimeData(const QMimeData *copy)
     }
 }

+DeclarativeMimeData *DeclarativeMimeData::wrap(const QMimeData *source)
+{
+    auto mimeData = new DeclarativeMimeData();
+    mimeData->m_wrapped = source;
+
+    const DeclarativeMimeData *declarativeMimeData = qobject_cast<const DeclarativeMimeData *>(source);
+    if (declarativeMimeData) {
+        mimeData->setSource(declarativeMimeData->source());
+    }
+    return mimeData;
+}
+
+QStringList DeclarativeMimeData::formats() const
+{
+    QStringList formats = QMimeData::formats();
+    if (m_wrapped) {
+        const auto wrappedFormats = m_wrapped->formats();
+        for (const QString &format : wrappedFormats) {
+            if (!formats.contains(format)) {
+                formats.append(format);
+            }
+        }
+    }
+    return formats;
+}
+
+QVariant DeclarativeMimeData::retrieveData(const QString &mimeType, QMetaType type) const
+{
+    if (m_wrapped && !QMimeData::formats().contains(mimeType) && m_wrapped->hasFormat(mimeType)) {
+        const_cast<DeclarativeMimeData *>(this)->QMimeData::setData(mimeType, m_wrapped->data(mimeType));
+    }
+    return QMimeData::retrieveData(mimeType, type);
+}
+
 QUrl DeclarativeMimeData::url() const
 {
     if (this->hasUrls() && !this->urls().isEmpty()) {
diff --git a/src/qmlcontrols/draganddrop/DeclarativeMimeData.h b/src/qmlcontrols/draganddrop/DeclarativeMimeData.h
index 39b620f6..80244b63 100644
--- a/src/qmlcontrols/draganddrop/DeclarativeMimeData.h
+++ b/src/qmlcontrols/draganddrop/DeclarativeMimeData.h
@@ -11,6 +11,7 @@
 #include <QColor>
 #include <QJsonArray>
 #include <QMimeData>
+#include <QPointer>
 #include <QQuickItem>
 #include <QUrl>

@@ -106,6 +107,12 @@ public:
      */
     DeclarativeMimeData(const QMimeData *copy);

+    /*
+     * Creates a MimeData that reads the data of \a source only when it is asked for,
+     * so that hovering a drag doesn't transfer all of it from the source application.
+     */
+    static DeclarativeMimeData *wrap(const QMimeData *source);
+
     QUrl url() const;
     void setUrl(const QUrl &url);

@@ -133,6 +140,8 @@ public:
      */
     Q_INVOKABLE QByteArray getDataAsByteArray(const QString &format);

+    QStringList formats() const override;
+
     /*
     QString text() const;                //TODO: Reimplement this to issue the onChanged signals
     void setText(const QString &text);
@@ -148,8 +157,12 @@ Q_SIGNALS:
     void colorChanged();
     void sourceChanged();

+protected:
+    QVariant retrieveData(const QString &mimeType, QMetaType type) const override;
+
 private:
     QQuickItem *m_source;
+    QPointer<const QMimeData> m_wrapped;
 };

 #endif // DECLARATIVEMIMEDATA_H
